export function histGet(metric, year) {
  if (!metric) return null;
  const i = year - metric.start;
  if (i < 0 || i >= metric.v.length) {
    const clampIdx = i < 0 ? 0 : metric.v.length - 1;
    return metric.v[clampIdx] != null ? metric.v[clampIdx] : nearest(metric, clampIdx);
  }
  if (metric.v[i] != null) return metric.v[i];
  return nearest(metric, i);
}
function nearest(metric, i) {
  for (let d = 1; d < metric.v.length; d++) {
    if (i - d >= 0 && metric.v[i - d] != null) return metric.v[i - d];
    if (i + d < metric.v.length && metric.v[i + d] != null) return metric.v[i + d];
  }
  return null;
}
